    "answer_id": "Yang membatalkan wudu:<br>1. Sesuatu yang keluar dari depan dan belakang.<br>2. Keluarnya darah, nanah, atau cairan kuning dari tubuh.<br>3. Muntah yang memenuhi mulut.<br>4. Pingsan.<br>5. Gila.<br>6. Tidur dalam posisi miring, atau bersandar pada sesuatu yang jika diangkat akan jatuh.<br>7. Tertawa dalam shalat yang memiliki rukuk dan sujud, sehingga terdengar oleh orang di sampingnya.",
