    "answer_tr": "آبدست المقله مشغول اولدیغی تقدیرده جنازه نمازينك فوت اولا جغندن قورقان كيمسه، جنازه نك وليسى دكلسه تیمم ايده رك جنازه نمازيني قيلار.<br>بایرام نمازينك فوت اولا جغندن قورقان کیمسه تیمم ايده رك نمازيني قيلار.<br>• جمعه نمازی قیلاجق اولان کیمسه آبدست المقله مشغول اولديغي تقديرده نمازينك كچمه سندن قور قارسه تیمم ایده مز. آبدست آلمق مجبوریتنده در جمعه يه يتيشير سه قيلار یتیشه مز ایسه او کله نمازینی ٤ رکعت اولارق قیلار.<br>• وقتك دار لغندن دولایی آبدست آلینجیه قدر وقتك چيقما سندن قورقان کیمسه ده تیمم ایتمز آبدست آلوب نمازینی قضا اولارق قيلار.",
    "question_id": "Apakah boleh bertayamum untuk mengejar shalat?",
    "answer_id": "• Jika seseorang khawatir akan tertinggal shalat jenazah karena sibuk berwudu, dan dia bukan wali (yang bertanggung jawab) atas jenazah tersebut, maka dia boleh bertayamum dan mengerjakan shalat jenazah.<br>• Jika seseorang khawatir akan tertinggal shalat Id karena sibuk berwudu, maka dia boleh bertayamum dan mengerjakan shalatnya.<br>• Namun, jika seseorang yang akan mengerjakan shalat Jumat khawatir akan tertinggal shalat jika sibuk berwudu, dia tidak boleh bertayamum. Dia harus berwudu. Jika dia sempat mengerjakan Jumat, dia shalat Jumat. Jika tidak, dia mengerjakan shalat Zuhur empat rakaat sebagai qada.<br>• Seseorang yang khawatir waktu shalat akan habis jika dia berwudu karena waktu yang sempit, dia tidak boleh bertayamum. Dia harus berwudu dan mengerjakan shalatnya sebagai qada.",
