    "answer_tr": "صاحب عذر عذر دوام ایتدیکي حالده فرض نماز ادا ايده جك قدر وقت بولامایان و بو حالی اوزره کامل بر نماز وقتی کچن و داها صوکراده هر نماز وقتنده اك از بر دفعه تکرار ایدن بر عذری بولونان کیمسه در.<br>• استحاضه لی قادین بول آقینتیسی اولان کیمسه بورنندن دائما قان آقان کیمسه و دواملی آقینتی یاپان یارا صاحبی کیشیلر هر نماز وقتنده آبدست آلوب او آبدست ایله ایسته دیکی قادار فرض و نافله نماز قيلا بيلير.<br>• وقت چیقدیغنده اونلرك آبدستلری بوزولور دیگر بر نماز ایچون یکیدن آبدست آلمالری لازمدر.",
