    "question_tr": "نجاستلر قاچ قسمدر و نه لر در؟",
    "answer_tr": "نجاستلر ایکی قسمدر:<br>۱- نجاست غلیظه (آغیر، قالین پیسلکلر): انسان وجودندن چیقمش اولان و آبدستی ویا غسلی ایجاب ایدن بوتون شیلر نجاست غلیظه‌در. مثلا: انسانك أوك و آرقادن چیقان پیسلکی، أتی ییئنمه‌ین حیوانلرك بولی، دیشقیسی و صالیاسی، طاووق، قاز و أوردکك دیشقیسی، قان، ایرین، منی، مذی، ودی، آغیز طولوسی قوصمق، شراب و دیگر حرام ایچکیلر.<br>حکمی: بو نجاستلر، کییسیلرده، بدنده ویا نماز قیلیناجاق یرده بولونورسه قاتی اولانلرك ۳،۲ (اوچ ویرکول ایکی) غرامدن فضله‌سی، صیوی اولانلرك ایسه أل آیاسی قادار ویا دها فضله‌سی نمازه مانعدر.<br>۲- نجاست خفیفه (خفیف پیسلکلر): آتك بولی، أتی ییئن اهلی و یابانی حیوانلرك پیسلکی، أتی ییئنمه‌ین قوشلرك دیشقیسیدر.<br>حکمی: بو نجاستلر اصابت ایتدیکی عضوك ویا ألبسه‌نك دورتده برندن فضله ایسه نمازه مانعدر.",
    "question_id": "Ada berapa jenis najis dan apa saja itu?",
    "answer_id": "Najis ada dua macam:<br>1. Najis ghalizah (najis berat/tebal): semua yang keluar dari tubuh manusia dan mewajibkan wudu atau mandi adalah najis ghalizah. Contohnya: kotoran yang keluar dari depan dan belakang manusia, air kencing, kotoran, dan air liur hewan yang dagingnya tidak dimakan, kotoran ayam, angsa, dan bebek, darah, nanah, mani, madzi, wadi, muntah sepenuh mulut, khamar dan minuman haram lainnya.<br>Hukumnya: jika najis ini terdapat pada pakaian, badan, atau tempat salat, maka yang padat lebih dari 3,2 (tiga koma dua) gram, dan yang cair seluas telapak tangan atau lebih, menghalangi sahnya salat.<br>2. Najis khafifah (najis ringan): air kencing kuda, kotoran hewan jinak dan liar yang dagingnya dimakan, dan kotoran burung yang dagingnya tidak dimakan.<br>Hukumnya: najis ini menghalangi sahnya salat jika lebih dari seperempat anggota badan atau pakaian yang terkena.",
