    "answer_tr": "• صباح نمازينك وقتي فجر ثانى طوغدیغی زمان ،باشلار کونش طوغونجيه قدر دوام ايدر.<br>• أو كله نمازينك وقتى كونشك زوالندن صوكره ،باشلار امام اعظم حضرتلرینه كوره هر شيئك كولكه سی ایکی مثلی اولونجيه قادار، امامينه كوره ايسه هر شيئك كولكه سی بر مثلی اولونجيه قدر دوام ایدر<br>• ایکندی نمازينك وقتی هر ایکی کوروشه کوره، أو كله وقتي چيقديغی زمان ،باشلار کونش با تنجه صوكه إيرر.<br>• اقشام نمازينك وقتی کونش با تدیغی زمان ،باشلار شفق با تدیغي زمان صوكه إيرر .<br>• یاتسی نمازينك وقتي شفق باتدیغی زمان ،باشلار فجر طوغمادن از أو كجه كی وقته قدر دوام ایدر .",
    "question_id": "Apa saja waktu-waktu shalat?",
    "answer_id": "• Waktu shalat Subuh: Dimulai ketika fajar shadiq (fajar kedua) terbit, dan berlanjut hingga matahari terbit.<br>• Waktu shalat Zuhur: Dimulai setelah tergelincirnya matahari. Menurut Imam A'zam, berlanjut hingga bayangan setiap benda mencapai dua kali panjangnya. Menurut kedua Imam (Abu Yusuf dan Muhammad), berlanjut hingga bayangan setiap benda mencapai satu kali panjangnya.<br>• Waktu shalat Ashar: Menurut kedua pandangan (Imam A'zam dan kedua Imam), dimulai ketika waktu Zuhur berakhir, dan berakhir ketika matahari terbenam.<br>• Waktu shalat Maghrib: Dimulai ketika matahari terbenam, dan berakhir ketika syafaq (mega merah) menghilang.<br>• Waktu shalat Isya: Dimulai ketika syafaq menghilang, dan berlanjut hingga sesaat sebelum fajar terbit.",
