    "question_id": "Apa saja yang membatalkan shalat?",
    "answer_id": "Yang membatalkan salat:<br>1. Berbicara dan tertawa hingga terdengar oleh dirinya sendiri.<br>2. Merintih dengan mengucapkan \"ah\".<br>3. Menangis.<br>4. Memalingkan wajah dan dada dari kiblat tanpa uzur.<br>5. Sengaja memberi salam atau menjawab salam.<br>6. Mengunyah permen karet.<br>7. Menyisir rambut atau jenggot.<br>8. Membaca Al-Qur'an dengan salah sampai merusak makna.<br>9. Mengangkat kedua kaki sekaligus dari tanah ketika sujud.<br>10. Berjalan sejauh dua saf dalam satu rakaat.",
