    "answer_tr": "جماعت ایله نماز قیلمانك حکمی: سنت مؤکده در.<br>امامته اك لایق اولانلر: ۱- سنتی اك أیی بیلندر. (اکر اوراده بولونانلر سنتی بیلمك باقیمندن مساوی ایسه‌لر)<br>۲- قرائتی أك کوزل اولان. (قرائت باقیمندن ده مساوی ایسه‌لر)<br>۳- اك وَرَعْ و تقوی صاحبی اولانی. (ینه مساوی ایسه‌لر)<br>٤- اك یاشلیلری امام اولور.<br>• کوله، بدوی، فاسق، ایکی کوزی کور و ولد زنا اولان کیمسه‌نك نماز قیلدیرماسی مکروهدر. فقط امام اولسه‌لر نماز جائز اولور.",
