    "answer_tr": "کراهت و قتلری او چدر طلوع استوى غروب یعنی کونش طوغارکن کونش تام زوال وقتنده ایکن و کونش با تارکن نماز قيلمق جائز دکلدر بو اوچ وقتندن اول حضر لانمش جنازه اوزرینه بو وقتلرده نماز قیلینماز ينه أو كجه دن اوقونمش بر سجده آیتندن طولایی تلاوت سجده سی ده یا پیلماز آنجق او كونك ايكيندى نمازينك فرضى كونش باتمق اوزره ایکن قيلينا بيلير.<br>صباح نمازندن صوکره کونش طوغانه قدر ایکیندی نمازندن صوکره کونش باتانه قدر نافله نماز قيلمق مكروهدر. بو ایکی وقتده کچمش فرض نماز لر قضا ایدیله بیلیر تلاوت سجده سی یا پیلا بیلیر.<br>کعبه معظمه يي طواف ايتدكدن صوكره قیلینماسی کره کن ایکی رکعت نماز بو ایکی وقتده قیلینماز.",
    "question_id": "Apa saja waktu-waktu karahah (terlarang/dibenci untuk shalat)?",
    "answer_id": "• Waktu-waktu karahah ada tiga: thulu', istiwa', dan ghurub, yaitu ketika matahari terbit, ketika matahari tepat di tengah (zawal), dan ketika matahari terbenam; pada waktu-waktu itu salat tidak sah. Jenazah yang sudah disiapkan sebelum tiga waktu ini tidak disalatkan pada waktu-waktu tersebut. Demikian pula sujud tilawah karena ayat sajdah yang dibaca sebelumnya tidak dilakukan. Hanya saja salat fardu Asar hari itu boleh dikerjakan ketika matahari hampir terbenam.<br>• Setelah salat Subuh hingga matahari terbit, dan setelah salat Asar hingga matahari terbenam, makruh mengerjakan salat sunah. Pada dua waktu ini salat fardu yang terlewat boleh diqada dan sujud tilawah boleh dilakukan.<br>• Dua rakaat salat yang semestinya dikerjakan setelah tawaf Ka'bah Mu'azzamah tidak dikerjakan pada dua waktu ini.",
