    "question_tr": "سهو سجده سنك حكمى نه در؟ نه زمان إيجاب ايتديكني و نصل یا پیلدیغنی سویله یکز؟",
    "answer_tr": "• نمازده بر فعلك فضله ويا أكسيك يا پيلمه سی حالنده سلامدن صوكره سهو سجده سی واجبدر.<br>• واجبك ترك و تأخيرنده، فرضك يالكز تأخير نده لازم كلير.<br>• یا پیلیشی: سهو سجده سی ایجاب ایتدیکی زمان \" التحيات \"بي اوقود قدن صوکره ایکی طرفه سلام ويريلير.\" الله اكبر \" دييه تكبير كيتيره رك آرقه آرقه یه ایکی سجده یا پیلیر ایکنجی سجده دن صوکره اوتوروب \" التحيات، اللهم صل اللهم بارك و ربنا \" دعالری او قونارق سلام ويريلير سهو سجده سی یا پاجق کیمسه امام ایسه؛ بالکز صاغ طرفنه سلام ویروپ سهو سجده سی یا پار.",
    "question_id": "Apa hukum sujud sahwi (sujud lupa)? Kapan diwajibkan dan bagaimana cara melakukannya?",
    "answer_id": "• Sujud sahwi adalah wajib jika terjadi kelebihan atau kekurangan dalam suatu perbuatan shalat, setelah salam.<br>• Sujud sahwi menjadi wajib jika meninggalkan atau menunda wajib, dan jika hanya menunda fardu.<br>• Cara melakukannya: Ketika sujud sahwi diwajibkan, setelah membaca \"At-Tahiyat\", ia mengucapkan salam ke kedua sisi. Kemudian ia takbir \"Allahu Akbar\" dan melakukan dua sujud secara berurutan. Setelah sujud kedua, ia duduk dan membaca doa \"At-Tahiyat, Allahumma shalli, Allahumma barik, dan Rabbana\", lalu mengucapkan salam.<br>• Jika orang yang akan melakukan sujud sahwi adalah imam, ia hanya mengucapkan salam ke sisi kanan, lalu melakukan sujud sahwi.",
