    "question_tr": "خسته نمازینی نصل قیلار؟",
    "answer_tr": "۱- خسته عذری سببیله آیاقده نماز قیلمایه قادر اولمادیغی زمان، نمازینی رکوع و سجده ایله اوتورارق قیلار.<br>۲- اکر رکوع و سجده‌یه کوجی یتمزسه؛ سجده‌سنی رکوعندن آشاغی اولمق اوزره ایماء ایده‌رك قیلار.<br>۳- خسته اوتورمایه مقتدر دکلسه؛ صیرت اوستی یاتار و آیاقلرینی قبله‌یه طوغری اوزاتارق رکوع و سجده‌یی ایماء ایله یاپارق نمازینی قیلار.<br>٤- ایماء ایتمیه ده کوجی یتمزسه؛ نمازینی تأخیر ایدر. کوز، قاش و قلب ایله ایماء اولماز.<br>• بر کیمسه ایماء ایله نماز قیلارکن، رکوع و سجده اوزرینه قادر اولسه؛ - ضعیف اوزره قوتلی یی بناء ایتمك اولاجغندن - نمازی یکیدن قیلار.",
    "question_id": "Bagaimana cara shalat orang sakit?",
    "answer_id": "1. Jika orang sakit karena uzurnya tidak mampu salat berdiri, ia salat dengan duduk sambil rukuk dan sujud.<br>2. Jika ia tidak mampu rukuk dan sujud, ia salat dengan isyarat (anggukan), dengan menjadikan sujudnya lebih rendah daripada rukuknya.<br>3. Jika orang sakit tidak mampu duduk, ia berbaring telentang, menjulurkan kakinya ke arah kiblat, dan salat dengan berisyarat untuk rukuk dan sujud.<br>4. Jika berisyarat pun tidak mampu, ia menunda salatnya. Isyarat dengan mata, alis, dan hati tidak sah.<br>• Jika seseorang yang salat dengan isyarat menjadi mampu rukuk dan sujud di tengah salat, ia mengulang salatnya dari awal, karena (melanjutkannya) berarti membangun yang kuat di atas yang lemah.",
