    "question_tr": "سجده آیتلری قاچ برده و نره لرده در؟ حکمنی سویله یکز و یا پیلیشنی آکلاتکز؟",
    "answer_tr": "سجده آیتلری قرآن کریمده اون دورت یرده در.<br>سجده آیتلری: ۱- اعراف، ۲- رعد، ۳- نحل، ٤- اسری، ٥- مریم، ٦- حج، ۷- فرقان، ۸- نمل، ۹- سجده، ۱۰- ص، ۱۱- فصلت، ۱۲- نجم، ۱۳- انشقاق، ۱٤- علق.<br>حکمی: اوقویان و دینله‌ین اوزرینه واجبدر.<br>یاپیلیش شکلی: سجده یاپاجق کیمسه قبله‌یه دونر. أللرینی قالدیرمه‌دن تکبیر آلارق سجده‌یه واریر. سجده‌ده اوچ دفعه \"<span lang='ar' dir='rtl'>سُبْحَانَ رَبِّيَ الْأَعْلَى</span>\" در. صوکره تکبیر آلارق آیاغه قالقارکن \"<span lang='ar' dir='rtl'>سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ</span>\" در.",
    "question_id": "Ada berapa tempat dan di mana saja ayat-ayat sujud tilawah? Apa hukumnya dan bagaimana cara melakukannya?",
    "answer_id": "• Ayat-ayat sujud tilawah ada empat belas tempat dalam Al-Qur'an.<br>• Ayat-ayat sujud tilawah: 1- Al-A'raf, 2- Ar-Ra'd, 3- An-Nahl, 4- Al-Isra', 5- Maryam, 6- Al-Hajj, 7- Al-Furqan, 8- An-Naml, 9- As-Sajdah, 10- Sad, 11- Fussilat, 12- An-Najm, 13- Al-Insyiqaq, 14- Al-Alaq.<br>• Hukumnya: Wajib bagi yang membaca dan yang mendengar.<br>• Cara melakukannya: Orang yang akan sujud tilawah menghadap kiblat, bertakbir tanpa mengangkat tangan, lalu bersujud. Dalam sujud, ia mengucapkan \"Subhana Rabbiyal A'la\" tiga kali. Kemudian, ia bertakbir dan bangkit berdiri sambil mengucapkan \"<span lang='ar' dir='rtl'>سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَ إِلَيْكَ الْمَصِيرُ</span>\".",
