    "question_tr": "وطن قاچ قسمدر ؟",
    "answer_tr": "وطن اوچ قسمدر: ١- وطن اصلی ٢- وطن اقامت ٣- وطن سکنی<br>وطن اصلی: کیشینك طوغدیغی ویا أولْندیکی یردر. یاشامایه نیت ایدوپ آیریلمق ایستهمهدیکی یرده وطن اصلی در. وطن اصلی آنجق وطن اصلی ایله بوزولور. بر کیشینك بردن فضله خانمی اولوپ هر برهری آیری آیری شهرلرده اولسهلر هیچ برنده سفری اولماز.<br>وطن اقامت: مسافرك أك آز اون بش کون قالمایه نیت ایتدیکی و وطن اصلیسنه (٩٠) طوقسان کیلومتره مسافهده بولونان یردر. بوراده نمازلر قیصالتیلماز. وطن إقامت؛ وطن اصلی ایله و باشقه بر وطن اقامت ایله بوزولور. وطن سکنی ایله بوزولماز.<br>وطن سکنی: مسافرك اون بش کوندن آز قالمایه نیت ایتدیکی و اصل وطننه (٩٠) طوقسان کیلومتره ویا دها فضله مسافهده بولونان یردر. بوراده دورت رکعتلی فرضلر ایکی رکعت قیلینیر.<br>• مسافر بر کیمسه سفرده قضایه قالان دورت رکعتلی فرضلری، سفرده ویا مَمْلَکَتنه دوندیکنده ایکی رکعت اولارق قضاء ایدر. مقیم ایکن قضایه قالان نمازلری ایسه؛ دورت رکعت اولارق قضاء ایدر.",
    "question_id": "Ada berapa jenis Watan (tempat tinggal)?",
    "answer_id": "Watan ada tiga jenis: 1. Watan Asli 2. Watan Iqamah 3. Watan Sukna<br>Watan Asli: tempat seseorang dilahirkan atau tempat ia menikah. Tempat yang ia niatkan untuk menetap dan tidak ingin meninggalkannya juga watan asli. Watan asli hanya batal dengan watan asli (yang lain). Jika seseorang memiliki lebih dari satu istri dan masing-masing tinggal di kota yang berbeda, ia tidak menjadi musafir di kota mana pun dari kota-kota itu.<br>Watan Iqamah: tempat yang musafir niatkan untuk tinggal paling sedikit lima belas hari dan berjarak (90) sembilan puluh kilometer dari watan aslinya. Di sini salat tidak diqasar. Watan iqamah batal dengan watan asli dan dengan watan iqamah yang lain; tidak batal dengan watan sukna.<br>Watan Sukna: tempat yang musafir niatkan untuk tinggal kurang dari lima belas hari dan berjarak (90) sembilan puluh kilometer atau lebih dari watan aslinya. Di sini salat fardu empat rakaat dikerjakan dua rakaat.<br>• Musafir yang meninggalkan salat fardu empat rakaat ketika safar, mengqadanya dua rakaat, baik masih dalam safar maupun setelah kembali ke negerinya. Adapun salat yang tertinggal ketika mukim, diqada empat rakaat.",
