    "question_id": "Apa perbedaan antara khotbah Jumat dan khotbah Id?",
    "answer_id": "1. Khotbah Jumat adalah syarat sahnya shalat Jumat (yaitu fardu), sedangkan khotbah Id adalah sunah.<br>2. Khotbah Jumat dibacakan sebelum shalat, sedangkan khotbah Id dibacakan setelah shalat.<br>3. Shalat Jumat tidak sah tanpa khotbah, sedangkan shalat Id sah (tanpa khotbah). Namun, ia telah melakukan perbuatan makruh karena meninggalkan sunah.<br>4. Dalam khotbah Jumat, pembahasan apa saja boleh. Dalam khotbah Id, pada Idul Fitri dibahas tentang zakat fitrah, dan pada Idul Adha dibahas tentang hukum-hukum kurban dan takbir tasyrik.",
