    "answer_tr": "جنازه نمازینك حکمی: فرض کفایه در.<br>جنازه نمازینك قیلینیشی: دورت تکبیر و بر قیام ایله أدا ایدیلیر. بو نمازده سجده و رکوع یوقدر. امام أولونك کُوکْسی حذاسنده دورور. جماعت ده آرقاسنده صَفْ طوتار. جماعته أولونك ارکك ویا قادین اولدیغنی دویورور. اوکا کوره نیت ایدیلیر. یعنی \"الله ایچون نمازه، میّت ایچون دعایه، اَرْ کیشی (ویا خاتون کیشی) نیّتنه اویدوم حاضر اولان امامه\" دیه قلبًا نیت ایدوب امامك آرقاسندن تکبیر آلینیر. ایلك تکبیری آلیرکن ألّلر قولاق حذاسنه قدر قالدیریلوب کوبك آلتنده باغلانیر. \"سبحانك\" \"و جل ثناؤك\" ایله اوقونور. بوندن صوکرا ألّلر قالدیریلمادن ایکنجی بر تکبیر آلینیر. بو تکبیرلری امام آشکار، جماعت ایسه کیزلی آلیر. \"اللهم صل و اللهم بارك.\" اوقونور. بوندن صوکرا اوچنجی تکبیر آلینیر و جنازه دعاسی اوقونور. جنازه دعاسنی بیلمهینلر بوراده \"اللهم انا نستعینك\" یی یعنی قنوت دعاسنی ویا دعا نیتی ایله فاتحهء شریفهیی اوقورلر. داها صوکرا دوردنجی تکبیر آلینیر، ألّلر یان طرفه بیراقیلوب سلام ویریلیر.",
    "question_id": "Apa hukum shalat jenazah? Bagaimana cara mengerjakannya?",
    "answer_id": "Hukum salat jenazah: fardu kifayah.<br>Cara mengerjakan salat jenazah: dikerjakan dengan empat takbir dan satu kali berdiri (qiyam). Dalam salat ini tidak ada sujud dan rukuk. Imam berdiri sejajar dengan dada mayit, dan jamaah membuat saf di belakangnya. Imam memberitahukan kepada jamaah apakah mayit itu laki-laki atau perempuan, lalu niat disesuaikan dengannya. Yaitu berniat dalam hati: \"Aku berniat salat karena Allah, berdoa untuk mayit laki-laki (atau perempuan) ini, mengikuti imam yang hadir ini\", lalu bertakbir di belakang imam. Ketika takbir pertama, kedua tangan diangkat sejajar telinga lalu disedekapkan di bawah pusar, dan dibaca \"Subhanakallahumma\" beserta \"wa jalla tsana'uka\". Kemudian tanpa mengangkat tangan dilakukan takbir kedua; takbir-takbir ini dikeraskan oleh imam dan dipelankan oleh jamaah. Lalu dibaca \"Allahumma shalli\" dan \"Allahumma barik\". Kemudian takbir ketiga dan dibaca doa jenazah. Yang tidak hafal doa jenazah membaca \"Allahumma inna nasta'inuka\" yakni doa qunut, atau Al-Fatihah dengan niat doa. Kemudian takbir keempat, kedua tangan dilepas ke samping, lalu salam.",
