    "answer_tr": "اوروچ آلتی قسمدر:<br>١- فرض: رمضان اوروجنك أداسی، قضاء و کفارت اوروچلری در.<br>٢- واجب: بوزولان نافله اوروجك قضاسی و آداق اوروچلری در.<br>٣- سنت: محرم آیینك ٩ ایله برابر ١٠ (عاشوره) گونی طوتولان اوروچ در.<br>٤- مندوب: هر آیدن طوتولان اوچ کون اوروچ در.<br>٥- نافله: شو صاییلانلردن باشقه مکروه اولمیان اوروچلر نافله در.<br>٦- مکروه: یالکز عاشورا کونی طوتولان اوروچ در. رمضان بایرامنك برنجی کونی، قوربان بایرامنك بر، ایکی، اوچ و دوردنجی کونی اوروچ طوتمق تحریما مکروه در.",
    "question_id": "Oruç (Puasa) ada berapa jenis?",
    "answer_id": "Puasa ada enam jenis:<br>1. Fardu: puasa Ramadan secara ada', puasa qada, dan puasa kafarat.<br>2. Wajib: qada puasa nafilah yang dibatalkan dan puasa nazar.<br>3. Sunah: puasa pada hari ke-10 (Asyura) bulan Muharam beserta hari ke-9.<br>4. Mandub: puasa tiga hari setiap bulan.<br>5. Nafilah: puasa-puasa selain yang telah disebutkan yang tidak makruh adalah nafilah.<br>6. Makruh: puasa pada hari Asyura saja. Berpuasa pada hari pertama Idulfitri serta hari pertama, kedua, ketiga, dan keempat Iduladha adalah makruh tahrim.",
