    "answer_tr": "بیعك قسملری:<br>١- بیعِ صحیح (نافذ): عِوضلری اصلًا و وصفًا صحیح اولان آلیش ویریشدر. قویون صاتمق كبی.<br>٢- بیع فاسد: عوضلری اصلا صحیح اولوپ، وصفا صحیح اولمیان آلیش ویریشدر. هواده كی قوشی صاتمق كبی.<br>٣- بیع باطل: عوضلری اصلا و وصفا صحیح اولمیان آلیش ویریشدر. خنزیر و شراب صاتمق كبی.<br>٤- بیع موقوف: كچرلی اولماسی صاحبنك إذننه باغلی اولان آلیش ویریشدر. صبینك آلیش ویریشی كبی.<br>٥- بیع مكروه: جمعه نمازی وقتنده یاپیلان آلیش ویریشدر.",
    "question_id": "Sebutkan macam-macam jual beli!",
    "answer_id": "Macam-macam jual beli:<br>1. Bai' shahih (nafiz): jual beli yang kedua barang tukarannya (iwadh) sah secara asal dan sifatnya. Seperti menjual kambing.<br>2. Bai' fasid: jual beli yang kedua barang tukarannya sah secara asal, tetapi tidak sah secara sifatnya. Seperti menjual burung yang masih di udara.<br>3. Bai' batil: jual beli yang kedua barang tukarannya tidak sah, baik secara asal maupun sifatnya. Seperti menjual babi dan khamar.<br>4. Bai' mauquf: jual beli yang keberlakuannya bergantung pada izin pemiliknya. Seperti jual beli anak kecil (shabiy).<br>5. Bai' makruh: jual beli yang dilakukan pada waktu salat Jumat.",
