    "question_tr": "مخیَّرات قاچ قسمدر؟ مخیرلك مدتی نه قادار‌در؟",
    "answer_tr": "مخیرات اوچدر:<br>خیار شرط، خیار رؤیت، خیار عیب<br>خیار شرط: آلیش ویریش اثناسنده، شرط قوشولان بر شیدن طولایی، آلیجی و صاتیجی ایچون مخیرلك اولماسنه دینور.<br>مخیرلك مدتی: امام اعظم حضرتلرینه كوره: اوچ كوندر. اوچ كوندن آزی جائز، فضله سی جائز دكلدر.<br>إمامینه كوره: بلیرلی بر مدّت تعیین إیدیلدیكی تقدیرده جائز در.<br>خیار رؤیت: صاتیجینك ویا مشترینك، كورمه دكلری بر مالی صاتمه‌لری ویا صاتین آلمالری جائزدر. آنجق هر هانكی بر مالی كورمه‌دن صاتین آلان مشتری ایچون، مالی كوردیكی زمان مخیرلك حقی موجوددر. ایسترسه آلمقدن واز كچه‌بیلیر.<br>صاتیجی ایسه صاتمقدن واز كچه‌مز. چونكه اونك ایچون كورمه مخیرلكی یوقدر.<br>خیار عیب: بر مشتری؛ صاتین آلدیغی مالده قیمتنی اكسیلتن بر قصور (عیب) بولورسه مخیردر.<br>ایسترسه مالی او قصوریله برلكده قبول ایدر، ایسترسه آلدیغی كیمسه‌یه (تجّاره) كری ویره‌بیلیر.<br>عیب: تجارت اهلی كیمسه‌لر عندنده، مالك قیمتنی اكسیلتن قصورلره دینور.",
    "question_id": "Ada berapa macam khiyar? Berapa lama masa khiyar?",
    "answer_id": "Khiyar ada tiga:<br>Khiyar syarat, khiyar ru'yah, dan khiyar 'aib.<br>Khiyar syarat: hak memilih bagi pembeli dan penjual karena adanya syarat yang disepakati ketika jual beli berlangsung.<br>Masa khiyar: Menurut Imam A'zham (Abu Hanifah): tiga hari. Kurang dari tiga hari boleh, lebih dari itu tidak boleh.<br>Menurut dua imam (Abu Yusuf dan Muhammad): boleh, asalkan ditentukan jangka waktu tertentu.<br>Khiyar ru'yah: penjual atau pembeli boleh menjual atau membeli barang yang belum mereka lihat. Namun, pembeli yang membeli suatu barang tanpa melihatnya memiliki hak khiyar ketika ia melihat barang itu. Jika mau, ia boleh membatalkan pembelian.<br>Adapun penjual tidak boleh membatalkan penjualan, karena ia tidak memiliki khiyar ru'yah.<br>Khiyar 'aib: apabila pembeli menemukan cacat ('aib) yang mengurangi nilai pada barang yang ia beli, maka ia berhak memilih.<br>Jika mau, ia menerima barang itu beserta cacatnya; jika mau, ia boleh mengembalikannya kepada orang yang menjual kepadanya (pedagang).<br>'Aib: kekurangan yang mengurangi nilai harta menurut para pedagang.",
