    "question_tr": "ربا (فائز) قاچ قسمدر؟ حرام اولمه علّتی نه‌در؟",
    "answer_tr": "رباء ایكی قسمدر:<br>١- ربَای نسیئه: قارشیلغنده هیچ بر شی بولونمایان زیاده‌در. وَعْده دوروومینه كوره اَكْلَه‌نن فائزدر.<br>٢- ربای فَضْل (فضله لق رباسی): مثلی بر مالی، مثلیله ایكی عوضدن بریسنی دیكری اوزرینه زیاده ایله صاتمقدر.<br>حرام اولمه زمانی: جنسی، جنسی مقابلندن فضله اولارق صاتیلدیغنده حرام اولور.<br>نوط: أفندیسی ایله كوله آراسنده و دارِ حربده كی مسلمان ایله حَرْبی آراسنده فائز یوقدر.",
    "question_id": "Riba (bunga) ada berapa macam? Apa sebab (illat) keharamannya?",
    "answer_id": "Riba ada dua macam:<br>1. Riba nasi'ah: tambahan yang tidak ada imbalan apa pun sebagai gantinya. Yaitu bunga yang ditambahkan sesuai dengan tenggang waktu (penundaan).<br>2. Riba fadhl (riba kelebihan): menjual barang mitsli dengan barang mitsli, dengan melebihkan salah satu dari dua barang tukaran atas yang lain.<br>Waktu menjadi haram: menjadi haram ketika suatu jenis dijual dengan jenis yang sama secara berlebih dari imbangannya.<br>Catatan: Tidak ada riba antara tuan dan budaknya, serta antara seorang muslim dan kafir harbi di darul harb.",
