    "question_tr": "سَلَمك صحّتنك شرطلری نه‌لردر؟",
    "answer_tr": "صحیح اولماسنك شرطلری: امام اعظم حضرتلرینه كوره یدی شرط ایله جائز اولور:<br>١- جنسی معلوم اولماسی،<br>٢- نوعی معلوم اولماسی،<br>٣- صفتی (قالیته سی) معلوم اولماسی ،<br>٤- مقداری معلوم اولماسی،<br>٥- وعده‌سی معلوم اولماسی،<br>٦- أولچی، طارتی و صاییه كیرن ماللر كبی مقدارله ایلكیلی ایسه، سرمایه مقدارینك بیلنمه‌سی،<br>٧- یوكْلَه‌مَه مصرفی وارسه، نه‌ره‌ده تسلیم ایدیله جكینك بیلنمه‌سی.",
    "question_id": "Apa saja syarat sahnya akad salam?",
