    "answer_tr": "عقدِ صرفك صحیح اولماسنك شرطلری:<br>١- طرفلرك بربرلرندن آیریلمادن اوكجه، (نقدی) قارشیلقلی اولارق بربرلرینه تسلیم ایتمه‌لری شرطدر.<br>٢- طرفلرك بربرلرینه \"مخیرلك شرطی\" قوشمه حقلری یوقدر.<br>٣- صرف عقدی صیراسنده؛ طرفلردن هر هانكی بریسنك بدلی تأجیل ایتمه حقی یوقدر.<br>٤- آلتون آلتون ایله ویا كوموش كوموش ایله صاتیلدیغی زمان، بونلرك مقدارلرینك وزنًا (طارتی باقیمندن) بربرلرینه مساوی اولماسی شرطدر.",
    "question_id": "Apa saja syarat sahnya akad sharf?",
    "answer_id": "Syarat-syarat sahnya akad sharf:<br>1. Kedua belah pihak wajib saling menyerahkan (uang) secara timbal balik sebelum berpisah.<br>2. Kedua belah pihak tidak berhak saling mensyaratkan \"khiyar syarat\".<br>3. Ketika akad sharf, tidak ada satu pun pihak yang berhak menangguhkan pembayaran gantinya.<br>4. Ketika emas dijual dengan emas atau perak dengan perak, kadar keduanya wajib sama secara timbangan (wazn).",
