    "question_id": "Pada harta apa saja gadai tidak boleh?",
    "answer_id": "Harta yang tidak boleh digadaikan: Sebagaimana tidak boleh menggadaikan harta milik bersama (musya'), harta amanah, buahnya saja tanpa pohonnya, atau tanamannya saja tanpa ladangnya, demikian pula tidak boleh menggadaikan pohonnya saja tanpa buah atau tanahnya saja tanpa tanaman.<br>Menggadaikan barang-barang amanah seperti wadi'ah (titipan), harta mudharabah, dan harta syirkah juga tidak boleh.",
