    "answer_id": "Sebab-sebab yang mewajibkan hajr: 1. Masih kecil, yakni belum balig. 2. Berstatus budak. 3. Gila.<br>Tasharruf anak kecil tanpa izin walinya dan tasharruf budak tanpa izin tuannya tidak sah. Adapun orang gila, tasharrufnya tidak pernah sah sama sekali. Menurut dua imam (Abu Yusuf dan Muhammad), hajr juga diberlakukan atas orang safih (yang boros/bodoh mengelola harta) dan atas orang yang berutang jika para pemberi utangnya memintanya.",
