    "answer_id": "Syirkah ada dua macam:<br>1. Syirkah amlak (persekutuan kepemilikan): persekutuan dua orang pada suatu harta yang mereka beli bersama atau mereka warisi bersama.<br>2. Syirkah 'uqud: persekutuan antara dua orang atau lebih dengan modal dan keuntungan dimiliki bersama.",
