    "question_tr": "شركتِ عقود قاچ قسمدر و نه‌لردر؟",
    "answer_tr": "شركت عقود دورت قسمدر:<br>١- شركتِ مُفَاوَضَه: ایكی كیشینك مالده، تَصَرُّفْده و بورچده مساوی اولمق اوزره قوردقلری شركت در.<br>٢- شركتِ عنَانْ: ایكی ویا دها فضله كیشی طرفندن، سرمایه قونولارق عقد ایدیلن بر شركت در.<br>عنان شركتی، بو كون كه آنُونِمْ شركتلرینك بكزریدر.<br>٣- شركتِ صنایع: ایكی ترزی یاخود بر ترزی ایله بر بویاجی كبی ایكی صنعتكارك، باشقه‌لرندن ایش قبول ایتمك و اَلْده ایتدكلری قازانجی آرالرنده تقسیم ایتمك اوزره یاپدقلری اورتاقلقدر.<br>٤- شركتِ وجوه: ایكی كیشینك سرمایه‌لری اولمادیغی حالده، خَلْق و تُجَّارْلَر نَزْدِنْده‌كی إعتبارلرینه دایانارق، ویره‌سیه مال صاتون آلمق، بو ماللری صاتوب بورچلرینی اوده‌مك و اَلْده ایدیله‌جك كاری آرالرنده تقسیم ایتمك اوزره قوردقلری بر اورتاقلقدر.",
    "question_id": "Syirkah 'uqud ada berapa macam dan apa saja?",
    "answer_id": "Syirkah 'uqud ada empat macam:<br>1. Syirkah mufawadhah: syirkah yang didirikan oleh dua orang dengan kesetaraan dalam harta, tasharruf (pengelolaan), dan utang.<br>2. Syirkah 'inan: syirkah yang diakadkan oleh dua orang atau lebih dengan menanamkan modal.<br>Syirkah 'inan ini mirip dengan perseroan terbatas (anonim) pada masa sekarang.<br>3. Syirkah shana'i' (syirkah a'mal): persekutuan dua orang tukang, seperti dua penjahit atau seorang penjahit dengan seorang tukang celup, untuk menerima pekerjaan dari orang lain dan membagi penghasilan yang mereka peroleh di antara mereka.<br>4. Syirkah wujuh: persekutuan yang didirikan oleh dua orang yang tidak memiliki modal, dengan bersandar pada kepercayaan (reputasi) mereka di mata masyarakat dan para pedagang, untuk membeli barang secara kredit, menjual barang itu, melunasi utang-utangnya, lalu membagi keuntungan yang diperoleh di antara mereka.",
