    "answer_tr": "مضارَبه‌نك صوكه ایرمه سی:<br>١- سرمایه صاحبنك أولماسی<br>٢- مضَارِبك أولماسی.<br>٣- سرمایه صاحبنك عقلی مَلَكَه لرینی ییتیرمه سی.<br>٤- مضارِبك جنّتی.<br>٥- سرمایه صاحبنك سَفَهْ ویا حَجْرْ سببیله مَحْجُورِیَّتی. بوكا \"قاضی\" قرار ویره بیلیر.<br>٦- مضارِبك مَحْجُورِیَّتی.<br>٧- بللی بر زمانله صینیرلاندیریلمش مضارَبه عقدنده، مدتك دولماسی.<br>٨- سرمایه صاحبنك، مضارِبی عَزْلْ ایتمه‌سی<br>٩- مضارِبك اسْتِفَا ایده‌رك ایشی بیراقماسی.<br>١٠- دها تَصَرُّفْ وقوع بولمادن سرمایه نك تلف اولماسی.",
    "question_id": "Dengan berapa hal mudharabah berakhir?",
    "answer_id": "Berakhirnya mudharabah:<br>1. Meninggalnya pemilik modal.<br>2. Meninggalnya mudharib.<br>3. Hilangnya kemampuan akal pemilik modal.<br>4. Gilanya mudharib.<br>5. Pemilik modal berada di bawah hajr (pencegahan) karena safah (kebodohan mengelola harta) atau hajr. Hal ini dapat diputuskan oleh \"qadhi\".<br>6. Mudharib berada di bawah hajr.<br>7. Habisnya masa, pada akad mudharabah yang dibatasi dengan waktu tertentu.<br>8. Pemilik modal memberhentikan mudharib.<br>9. Mudharib mengundurkan diri dan meninggalkan pekerjaannya.<br>10. Rusak/musnahnya modal sebelum terjadi pengelolaan (tasharruf).",
