    "answer_tr": "٢- كَفَالَتْ بالْمَالْ: مال ویا پارایه كفیللك ده ایسه، آصل بورچلی مال یاده پارا بورجنی وَعْدَه‌سنده أوده‌مزسه، كفیل بونلری آلاجقلییه أوده‌مه‌یی اوزرینه آلمش اولور.<br>مال ایله ایلكیلی كفالت ایكی دورومده صوكه ایرر:<br>١- بورجك آلاجقلییه أودنمه‌سی ایله<br>٢- آلاجقلینك، كفیلی ویا آصیلی بورچدن اِبْرا ایتمه‌سی ایله كفالت صوكه ایرر.",
