    "answer_id": "2. Kafalah bil-mal (jaminan atas harta): adapun dalam penjaminan harta atau uang, jika orang yang berutang asli tidak membayar utang harta atau uangnya pada waktu jatuh temponya, maka penjamin telah menanggung kewajiban membayarnya kepada pemberi utang.<br>Kafalah yang berkaitan dengan harta berakhir dalam dua keadaan:<br>1. Dengan dilunasinya utang kepada pemberi utang,<br>2. Dengan pemberi utang membebaskan (ibra') penjamin atau orang yang berutang asli dari utang, maka kafalah pun berakhir.",
