    "answer_tr": "صُلْحْ عقدی اوچ قسمدر:<br>١- صُلْحْ مَعَ الْاِقْرَارْ: مُدَّعَی علیه، مُدَّعِی نك طلب ایتدیكی شیئی إقرار ایتمه‌سی اوزرینه واقع اولان صلح در.<br>٢- صُلْحْ مَعَ السُّكُوتْ: مُدَّعَی علیه، مُدَّعِی نك طلب ایتدیكی شیئی إقرار و إنكار ایتمه‌یوپ، سكوت ایتمه‌سی اوزره واقع اولان صلح در.<br>٣- صُلْحْ مَعَ الْاِنكَارْ: مُدَّعَی علیه، مُدَّعِی نك طلب ایتدیكی شیئی إنكار ایتمه‌سی اوزرینه واقع اولان صلح در.",
