    "answer_tr": "عُمْرَی: أوِینی باشقه‌سنه؛ أولونجیه قدار قوللانماسی ایچون هبه ایتمه‌یه دینور. بو جائزدر.<br>رُقْبَی ایسه جائز دكلدر. بو \"اكر بن سندن اوكجه أولورسه م، أوْ سنك در\" شكلنده بر تعهُّده دایانیر.<br>هبه‌دن واز كچمك (رجوع ایتمك): اكر یاقین آقْرَبَاسنه هبه ایتمش ایسه بوندن واز كچه‌مز.<br>یابانجی بر كیمسه‌یه هبه ایتمش ایسه واز كچه‌بیلیر.",
    "question_id": "Apa itu 'umra dan ruqba?",
    "answer_id": "'Umra: menghibahkan rumahnya kepada orang lain untuk dipakai sampai ia (penerima) meninggal. Ini boleh.<br>Adapun ruqba tidak boleh. Ruqba bersandar pada perjanjian semacam: \"Jika aku meninggal lebih dahulu darimu, rumah itu milikmu.\"<br>Menarik kembali hibah (ruju'): jika ia menghibahkan kepada kerabat dekatnya, ia tidak boleh menariknya kembali.<br>Jika ia menghibahkan kepada orang lain (bukan kerabat), ia boleh menariknya kembali.",
