    "answer_tr": "امانتی كیم قورور؟ امانت مالی، بِالذَّاتْ اونی آلانك كندیسنك و عائله‌سندن اولان بریسنك قوروماسی كره‌كیر. اونك قورونماسنی باشقه‌لرینه یاپدیراماز. آنجق أوِنْده یانغین اولورسه قومشوسنه تسلیم ایده‌بیلیر ویا كَمِی باتییورسه باشقه كَمِی یه آقتارابیلیر.<br>امانت ضَایِعْ اولونجه أوده‌نیرمی؟ ودیعه، اونی قورویانك ألنده بر امانتدر. بو باقیمدن بر تَجَاوُزْ اولمادن ضایع اولورسه أودنمه‌سی كركمز.",
    "question_id": "Siapa yang menjaga wadi'ah, dan apakah wajib diganti jika hilang?",
    "answer_id": "Siapa yang menjaga amanah? Harta amanah wajib dijaga sendiri oleh orang yang menerimanya atau oleh salah seorang dari keluarganya. Ia tidak boleh menyuruh orang lain menjaganya. Namun, jika terjadi kebakaran di rumahnya, ia boleh menyerahkannya kepada tetangganya, atau jika kapal tenggelam, ia boleh memindahkannya ke kapal lain.<br>Apakah amanah wajib diganti jika hilang? Wadi'ah adalah amanah di tangan orang yang menjaganya. Karena itu, jika hilang tanpa adanya kelalaian/pelanggaran (ta'addi), tidak wajib diganti.",
