    "answer_tr": "خُنْثَی: دوغان چوجوغك هم أركَكلك همده قادینلق عضوی اولورسه او چوجوق خنثی در.<br>اكر اركَكلك عضوندن بَوْلْ ایدییورسه اركك، قادینلق عضوندن بَوْلْ ایدییورسه قادین حكمنده در. ایكیسندن ده بول ایدییورسه هانكیسندن اوكجه كلییورسه اوكا تابع اولولونور. ایكیسندن ده عینی آنده بول ایدرسه، امام اعظم حضرتلرینه كوره چُوقْلُقْ معتبر دكلدر. امامینه كوره معتبردر. هانكیسنك غالب كلدیكی بیلینمه‌ین كیمسه‌یه‌ده خنثای مشكِل دینور.",
    "question_id": "Apa yang dimaksud dengan khuntsa?",
