    "answer_tr": "احْیَای مَوَاتْ: صو كسیلدیكی ایچون ویا صو غالب كلدیكی ایچون ویاخود ده بوكا بكزر زراعته مانع اولان شیلردن طولایی كندیسی ایله منفعتله‌نیلمه‌ین و او یرك نهایتنده بر انسان دوروب باغیرسه سَسِی ایشیتیلمه‌یه‌جك قدار اوزاقده اولان بوش آراضی در.<br>بر كیمسه امامك اذنی ایله او آراضی یی احیا ایدرسه اورایه صاحب اولور. اذنسز احیا ایدرسه صاحب اولماز.",
