    "question_tr": "نكاحك تعریفی و ركنی نه‌در؟ قاچ شاهد لازمدر و شاهدلرده آرانان وصفلر نه‌لردر؟",
    "answer_tr": "نكاح: كندیسنه نكاحی صحیح اولان بر قادیندان اركگك استفاده سینی حلال قیلان بر عقددر.<br>نكاحك ركنی: ایجاب و قبولدر. یعنی اَوْلَنه‌جك كیمسه‌لردن برینك \"سنی آلدم ویا كندیمی سكا ویردم\" دیمسی، دیگرینك ده \"قبول ایتدم\" دیمه‌سیدر. ایجاب و قبول هر ایكیسی ده ماضی ویا اك آزندن بریسی ماضی دیگری مضارع اولمق دورومنده در.<br>نكاحده شاهدلك: ایكی أركك ویَا بر أركك و ایكی قادینك شاهدلكی ایله عقد یاپیلیر.<br>شاهدلر؛ مسلمان، حر، عاقل، بالغ اولمالیدر.",
    "question_id": "Apa definisi nikah dan apa rukunnya? Berapa saksi yang diperlukan dan apa sifat-sifat yang disyaratkan pada saksi?",
    "answer_id": "Nikah: akad yang menghalalkan seorang laki-laki bersenang-senang (istimta') dengan perempuan yang sah dinikahinya.<br>Rukun nikah: ijab dan kabul. Yaitu salah satu dari kedua calon mempelai berkata \"Aku mengambilmu\" atau \"Aku serahkan diriku kepadamu\", dan yang lain berkata \"Aku terima\". Ijab dan kabul keduanya berbentuk madhi (lampau), atau sekurang-kurangnya salah satunya madhi dan yang lain mudhari'.<br>Saksi dalam nikah: akad dilangsungkan dengan kesaksian dua orang laki-laki, atau satu laki-laki dan dua perempuan.<br>Para saksi harus muslim, merdeka, berakal, dan balig.",
