    "question_id": "Siapakah mahram (muharramat) itu dan ada berapa macam?",
    "answer_id": "Muharramat: perempuan-perempuan yang haram dinikahi menurut agama. Ada tiga macam:<br>1. Yang haram karena nasab (garis keturunan):<br>1. Ibu-ibu 2. Anak-anak perempuan 3. Saudari-saudari perempuan 4. Bibi (khalah) 5. Bibi (tante) 6. Anak-anak perempuan dari saudari perempuan<br>2. Yang haram karena mushaharah (hubungan perkawinan):<br>1. Ibu mertua 2. Ibu tiri 3. Anak tiri perempuan 4. Menantu perempuan<br>3. Yang haram karena radha'ah (persusuan):<br>1. Ibu susuan 2. Anak perempuan susuan 3. Nenek susuan 4. Saudari susuan 5. Bibi susuan 6. Bibi (khalah) susuan<br>7. Anak-anak perempuan dari saudara dan saudari susuan.",
