    "answer_tr": "اهل كتاب ایله اولیلك؛ كتاب اهلی اولان خاتملرله اولنمك جائزدر. پوت پَرَسْتْ و آتشپرست خاتملرله اولنمك ایسه جائز دكلدر.<br>اگر بر پیغمبره ایمان و بر كتابی اقرار ایدرلرسه اوله‌نیلیر. بر كتابی اقرار ایتمز ایسه‌لر نكاحلانمق جائز دكلدر.<br>مسلمان قادینلرك ایسه، اهل كتاب اركككلرله – عینی وصفلری طاشیسه‌لر بیله اولنمه‌لرینه اذن ویریلمه‌مشدر.",
