    "answer_tr": "مهر مسمی: نكاح عقدی اثناسنده طرفلر آراسنده مقداری تثبیت ایدیلن مهره \"مهر مسمی\" دینیر. قادینه اوده نیشی اعتباری ایله، تمامًا ویا قسمًا پشین اولانه \"مهر معجل\" ویره سیه اولانه \"مهر مأجل\" دینیر.<br>مهر مثل: نكاح عقدی اثناسنده مهر قونوشولمامش اولورسه، بوراده بلیرله نه جك اولان مقداردر.",
