    "question_tr": "نكاح، كچرلیلكی باقیمندن قاچه آیریلیر و نكاح منعقد ایله نكاح باطلی ایضاح ایدیكز؟",
    "answer_tr": "نكاح، كچرلیلكی باقیمندن، حكم اولارق اوچه آیریلیر.<br>١- نكاحِ منعقد، ٢- نكاحِ باطل، ٣- نكاحِ فاسد<br>١- نكاحِ منعقد (صحیح نكاح): صحت شرطلرینی تمامًا جامع اولان نكاحدر.<br>٢- نكاحِ باطل: اوزرینه اصلا نكاح حكملری تَرَتُّبْ ایتمه‌ین نكاحدر.<br>مثلا: متعه نكاحی و مسلمان قادینك غیر مسلم اركك ایله نكاحی كبی<br>حكمی: باطل بر نكاح ایله نسب ثابت اولماز و عدت واجب اولماز.",
    "question_id": "Dari segi keabsahannya, nikah terbagi menjadi berapa? Jelaskan nikah mun'aqid dan nikah batil!",
    "answer_id": "Dari segi keabsahannya, nikah secara hukum terbagi tiga:<br>1. Nikah mun'aqid, 2. Nikah batil, 3. Nikah fasid<br>1. Nikah mun'aqid (nikah sahih): nikah yang memenuhi seluruh syarat sahnya.<br>2. Nikah batil: nikah yang sama sekali tidak menimbulkan hukum-hukum nikah.<br>Contoh: nikah mut'ah dan nikah perempuan muslimah dengan laki-laki non-muslim.<br>Hukumnya: dengan nikah batil, nasab tidak tetap dan iddah tidak wajib.",
