    "question_tr": "نكاح فاسدی ایضاح ایدیكز؟",
    "answer_tr": "٣-نكاحِ فاسد: اَوَّلْ امرده منعقد اولان آما صوكرادن بر مانع ایله بوزولان نكاحدر.<br>مثلا: – شاهدسز اولارق عقد ایدیلن نكاحلر – بر كیمسه‌نك اوچ طلاق ایله بوشادیغی خانمی ایله خُلَّه‌دن اوكجه تكرار عقد ایتدیكی نكاحلر – بر كیمسه‌نك كندی محرملرندن بری ایله بیله‌رك ویا بیلمیه‌رك یاپاجغی نكاحلر،<br>حكمی: فاسد نكاحلر حدِّ ذاتنده بر نكاح دكلدر. دخول بولونمادقجه عدت، مهر، نفقه لازم كلمز. دخول بولونورسه بونلر لازم كلیر.",
    "question_id": "Jelaskan nikah fasid!",
    "answer_id": "3. Nikah fasid: nikah yang pada awalnya terjadi (mun'aqid) tetapi kemudian rusak karena suatu penghalang.<br>Contoh: – nikah yang diakadkan tanpa saksi; – nikah seseorang yang mengakad ulang istri yang telah ia talak tiga sebelum terjadinya hulle (tahlil); – nikah yang dilakukan seseorang dengan salah satu mahramnya, baik ia mengetahui maupun tidak.<br>Hukumnya: nikah fasid pada hakikatnya bukanlah nikah. Selama belum terjadi dukhul (persetubuhan), tidak wajib iddah, mahar, dan nafkah. Jika telah terjadi dukhul, semua itu menjadi wajib.",
