    "question_tr": "مُوَقَّتْ نكاح نه در و حكمنی ایضاح ایدیكز؟",
    "answer_tr": "مُوَقَّتْ نكاح: نا محرم ( نكاحی حلال) اولان قادینلردن بری ایله شاهدلر حضورنده \"شو قدر مدتله، شو قدر مال مقابلنده سنك ایله اولنه‌یم \" دییه‌رك، ایكی طرفك ایجاب و قبولده بولونمالریدر. یوز سنه‌ده اولسه دوروم عینیدر.<br>حكمی : موقت نكاح باطلدر. بو اِزْدِوَاجْدن طوغان چوجوقلرك نسبی صحیح اولماز. مدتك اوزون ویا قیصه/ معلوم ویا مجهول اولماسنده فرق یوقدر. متعه نكاحی ده بویله در.",
    "question_id": "Apa itu nikah muwaqqat dan jelaskan hukumnya!",
    "answer_id": "Nikah muwaqqat: kedua belah pihak melakukan ijab dan kabul di hadapan para saksi dengan salah seorang perempuan non-mahram (yang halal dinikahi) dengan berkata, \"Aku menikah denganmu untuk jangka waktu sekian dengan imbalan harta sekian\". Sekalipun jangka waktunya seratus tahun, keadaannya tetap sama.<br>Hukumnya: nikah muwaqqat itu batil. Nasab anak-anak yang lahir dari perkawinan ini tidak sah. Tidak ada bedanya apakah jangka waktunya panjang atau pendek, diketahui atau tidak diketahui. Nikah mut'ah pun demikian.",
