    "question_tr": "غیر مسلمان قاری قوجه دن بری مسلمان اولسه نه یاپیلیر؟",
    "answer_tr": "قادین؛ قوجه‌سی كافر اولدیغی حالده مسلمان اولورسه، قاضی قوجاسنه اسلامی تكلیف ایدر. اگر مسلمان اولورسه زوجه‌سی كندیسنكدر. اگر مسلمان اولمایی رَدّ ایدرسه دَرْحَالْ آیریر.<br>قوجه؛ مسلمان اولوب، پُوتْ پَرَسْتْ بر خانمی وارسه اونا اسلام دینی تكلیف ایدیلیر. مسلمان اولدیغی تقدیرده قوجاسنك عائله‌سیدر. قبول ایتمه‌دیكی تقدیرده قاضی دَرْحَالْ آیریر. بر سماوی كتابه اینانان خانمك قوجه‌سی مسلمان اولورسه نكاحلری دوام ایدر.",
    "question_id": "Apa yang dilakukan jika salah satu dari pasangan suami istri non-muslim masuk Islam?",
    "answer_id": "Istri: jika ia masuk Islam sementara suaminya kafir, maka kadi menawarkan Islam kepada suaminya. Jika suami masuk Islam, istrinya tetap menjadi miliknya. Jika ia menolak masuk Islam, kadi segera memisahkan mereka.<br>Suami: jika ia masuk Islam dan memiliki istri penyembah berhala, maka agama Islam ditawarkan kepada istrinya. Jika istri masuk Islam, ia tetap menjadi keluarga suaminya. Jika tidak menerima, kadi segera memisahkan mereka. Jika suami dari seorang perempuan yang beriman kepada kitab samawi masuk Islam, maka nikah mereka tetap berlanjut.",
