    "question_tr": "رضاعك تعریفی نه در؟ مدتی نه قدردر؟ رضاعده قوللانیلان اصطلاحلر نه لردر؟",
    "answer_tr": "رضاع: خصوصی وقتده آدمینك كُوكْسُنْدن چوجوغك سوت اَمّه‌سیدر. رضاعك آزی و چوغی، امزیرمه مدتنده میدانه كلیرسه مساویدر و حراملق تعلق ایدر.<br>رضاع مدتی: امام اعظم حضرتلرینه كوره ٣٠ آی (ایكی بوچوق سنه)، امامینه كوره ایسه ایكی سنه‌در.<br>اِرْضَاعْ: امزیرمك. مُرْضِعَةٌ: سوت امزیرن قادین. رَضِیعْ: سوت امن چوجوق.",
    "question_id": "Apa definisi radha'ah (persusuan)? Berapa lama masanya? Apa istilah-istilah yang digunakan dalam radha'ah?",
    "answer_id": "Radha'ah: menyusunya seorang anak dari payudara manusia (perempuan) pada waktu tertentu. Sedikit atau banyaknya susuan sama saja jika terjadi dalam masa menyusui, dan menimbulkan keharaman (nikah).<br>Masa radha'ah: menurut Imam A'zham (Abu Hanifah) 30 bulan (dua setengah tahun), sedangkan menurut Imamain (Abu Yusuf dan Muhammad) dua tahun.<br>Irdha': menyusui. Murdhi'ah: perempuan yang menyusui. Radhi': anak yang menyusu.",
