    "question_tr": "طلاق نه در؟ قاچ قسمدر؟",
    "answer_tr": "طلاق: نكاح سببیله شرعًا ثابت اولان نكاح باغینی قالدیرمقدر.<br>طلاق، شكلی اعتباریله ٣ قسمدر: ١- احسن طلاق ٢- سنت طلاق ٣- بدعت طلاق<br>احسن طلاق: اركگك خانمنی بر طهر دونمنده بوشایوب، اوكا هیچ یاقلاشمادن ، قادینك عدتنی بیتیرمه سیدر.<br>سنت طلاق: اركگك خانمنی، هر طهر دونمنده برر طلاق ایله بوشاماسی و بو زمان ایچونده خانمنه یاقلاشمامش اولماسیدر.<br>بدعت طلاق: اركگك خانمنی بر كلمه ایله اوچ طلاق بردن بوشاماسی ویا بر طهر دونمنده اوچ آیری طلاق ایله بوشامش اولماسیدر.",
    "question_id": "Apa itu talak? Ada berapa macam?",
    "answer_id": "Talak: melepaskan ikatan nikah yang telah tetap secara syar'i dengan sebab nikah.<br>Ditinjau dari bentuknya, talak ada 3 macam: 1. Talak ahsan 2. Talak sunni 3. Talak bid'i<br>Talak ahsan: suami mentalak istrinya dalam satu masa suci, lalu tidak mendekatinya sama sekali hingga istri menyelesaikan iddahnya.<br>Talak sunni: suami mentalak istrinya satu talak pada setiap masa suci, dan selama masa itu ia tidak mendekati istrinya.<br>Talak bid'i: suami mentalak istrinya tiga sekaligus dengan satu kalimat, atau menjatuhkan tiga talak terpisah dalam satu masa suci.",
