    "originalNumber": 216,
    "question_tr": "طلاقِ رجعی و حكمی نه در ایضاح ایدیكز؟",
    "answer_tr": "طلاقِ رجعی: صریح آچیق لفظلرله ویریلن طلاقدر. (<span lang='ar' dir='rtl'>اَنْتِ طَالِقٌ</span>) كبی. بونی سویله‌ین كیمسه، بوشامایه نیت ایتسون ویا ایتمه‌سون، خانمنی بر طلاق رجعی ایله بوشامش اولور.دها فضله عَدَدَه نیت ایتسه دخی بر طلاق واقع اولور.<br>(<span lang='ar' dir='rtl'>اَنْتِ طَالِقٌ اِنْ شَاءَ اللّٰهُ</span>) دیرسه طلاق واقع اولماز.<br>كنوی لفظلردن ٣ طانه‌سی ده صریح لفظ حكمنده در كه شونلردر؛<br>١- عِدَّتْ بَكْلَه، ٢- رَحْمِنی تمیزله، ٣- سَنْ تَكْسِینْ، یَالْكِزْسِینْ.<br>حكمی: قوجه‌نك، عدت مدتی ایچونده خانمنه دونه‌بیلمه‌سیدر. یعنی نكاحی دوام ایتدیره‌بیلمه‌سیدر.",
    "question_id": "Jelaskan talak raj'i dan hukumnya!",
    "answer_id": "Talak raj'i: talak yang dijatuhkan dengan lafaz sharih (jelas/tegas), seperti (<span lang='ar' dir='rtl'>اَنْتِ طَالِقٌ</span>) \"engkau tertalak\". Orang yang mengucapkannya, baik berniat mentalak maupun tidak, telah mentalak istrinya dengan satu talak raj'i. Sekalipun ia berniat bilangan yang lebih banyak, tetap jatuh satu talak.<br>Jika ia berkata (<span lang='ar' dir='rtl'>اَنْتِ طَالِقٌ اِنْ شَاءَ اللّٰهُ</span>) \"engkau tertalak insya Allah\", maka talak tidak jatuh.<br>Ada 3 lafaz kinayah yang hukumnya seperti lafaz sharih, yaitu:<br>1. \"Hitunglah iddahmu\", 2. \"Bersihkan rahimmu\", 3. \"Engkau sendirian (satu-satunya)\".<br>Hukumnya: suami dapat kembali (rujuk) kepada istrinya selama masa iddah, yakni ia dapat melanjutkan nikahnya.",
