    "answer_tr": "طلاق باین: كنوی/آچیق اولمیان لفظلرله ویریلن طلاقدر. بو لفظلر طلاق حرفلرندن مشتق اولمیان، فقط طلاقده قوللانیلان لفظلردر.<br>مثلا: \"سَنْ آیریلمشسك، سَنكْ ایلْكَكْ كسیلمشدر، سَنْ آیْریسكْ، سَنْ حَرَمْسكْ، سَنی اَهْلنَه هبَه ایتدِمْ، سَنی بیرَاقْدِمْ، سَنْ حُرْسُكْ، بَاشنَه اُورْتُونی اَورْتُكْ، غُرْبَتَه چِیقْ\" كبی. بونلری سویله‌ین اركك \"بوشامه نیتی\" ایله سویله‌مه‌دكجه طلاق واقع اولماز.<br>حكمی: بو طلاق ایله آیریلق حاصل اولوب، اولیلك صوكه ایرر. قوجه‌نك، نكاحی دوام ایتدیرمكه حقی قالماز.",
    "question_id": "Jelaskan talak ba'in dan hukumnya!",
    "answer_id": "Talak ba'in: talak yang dijatuhkan dengan lafaz kinayah, yakni lafaz yang tidak tegas. Lafaz-lafaz ini tidak diambil dari huruf-huruf kata talak, tetapi digunakan untuk talak.<br>Contoh: \"Engkau telah berpisah, talimu telah putus, engkau terpisah, engkau haram, aku hibahkan engkau kepada keluargamu, aku lepaskan engkau, engkau merdeka, tutuplah kepalamu, pergilah merantau\" dan semisalnya. Laki-laki yang mengucapkannya, selama tidak mengucapkannya dengan \"niat talak\", maka talak tidak jatuh.<br>Hukumnya: dengan talak ini terjadilah perpisahan dan pernikahan berakhir. Suami tidak lagi berhak melanjutkan nikah.",
