    "answer_tr": "طلاق حادثه‌یه باغلی اولارق ویریله بیلیر: مثلا بر انسان خانمنه \"شونی یاپدیغك زمان، فلان یره كیرْدیكِكْ زمان، فلانجه ایله قونوشدیغك زمان بوش اول\" دیسه، طلاق واقع اولور.<br>طلاقی مكانه باغلامق جائز اولماز: مثلا بر انسان خانمنه \"سن اَوْده، اوواده، كولكه ده، كونشده بوش اول\" دیسه طلاق او آنده همان واقع اولور.",
