    "question_tr": "حضَانَه نه دیمكدر؟",
    "answer_tr": "حضَانَه: قاری-قوجه آیریلدقدن صوكرا چوجوغی، صلاحیتلی اولان كیمسه‌نك بلیرلی بر یاشه كلنجه‌یه (اركك یدی، قیز ییتیشكین اولونجه یه) قدر یاننده حمَایَه و تَرْبیَه ایتمه سیدر.<br>اَشْلَرْ آیریلدیغنده، آنه چوجوغك تربیه‌سنه دها اویغوندر. چونكه آنه شَفْقَتْلیدر. آنه اولمادیغی تقدیرده آنه‌نك ویا بابانك آنه‌سیدر.<br>اركك چوجوق؛ تك باشنه ییوب، ایچوب، البسه‌سنی كییوب و طهارتنی یاپنجه‌یه قدر آنه‌سی و نینه سنك باقماسی اولادر.<br>قیز چوجوق؛حیض كوروبنجه‌یه قدر آنه‌سی و نینه سنك یاننده اولماسی اولادر.",
    "question_id": "Apa yang dimaksud dengan hadhanah?",
    "answer_id": "Hadhanah: setelah suami istri berpisah, orang yang berwenang (berhak) melindungi dan mendidik anak di sisinya sampai anak mencapai usia tertentu (anak laki-laki tujuh tahun, anak perempuan sampai dewasa).<br>Ketika suami istri berpisah, ibu lebih layak mendidik anak, karena ibu lebih penyayang. Jika tidak ada ibu, maka hak itu milik ibunya ibu atau ibunya ayah (nenek).<br>Anak laki-laki: lebih utama diasuh oleh ibu dan neneknya sampai ia mampu makan, minum, berpakaian, dan bersuci sendiri.<br>Anak perempuan: lebih utama berada di sisi ibu dan neneknya sampai ia haid.",
