    "originalNumber": 231,
    "question_tr": "عتَاقْ، اسْتیلَادْ، مُكَاتَبْ و وَلَاء نه دیمكدر؟",
    "answer_tr": "عتَاقْ: كوله آزاد ایتمك دیمكدر.<br>مُدَبَّرْ: آزاد اولمسی، افندیسنك وفاتنه باغلی قیلینان كوله در.<br>اسْتیلَادْ: افندیسنك جاریه‌سندن چوجوق طلب ایتمه‌سیدر.<br>جاریه مولاسندن چوجوق دنیایه كتیردیكی زمان \"اُمُّ الْوَلَدْ\" اولور. صاتیشی ویا باشقاسنه ملك اولارق ویریلمسی جائز اولماز.<br>مُكَاتَبْ: آزاد اولمق ایچون افندیسی ایله بللی بر أجرت قارشیلغنده آكلاشان كوله در.<br>وَلَاء: آزاددن ویا ولیلك سوزلشمه‌سی یاپیلماسندن حاصل اولان حكمی بر یاقینلقدر.",
    "question_id": "Apa yang dimaksud dengan 'itaq, istilad, mukatab, dan wala'?",
    "answer_id": "'Itaq: memerdekakan budak.<br>Mudabbar: budak yang kemerdekaannya digantungkan pada wafatnya tuannya.<br>Istilad: tuan menghendaki anak dari budak perempuannya.<br>Ketika budak perempuan melahirkan anak dari tuannya, ia menjadi \"umm al-walad\". Ia tidak boleh dijual atau diberikan kepada orang lain sebagai milik.<br>Mukatab: budak yang bersepakat dengan tuannya untuk merdeka dengan imbalan bayaran tertentu.<br>Wala': kekerabatan hukmiyah yang timbul dari pemerdekaan budak atau dari perjanjian muwalah.",
