    "question_tr": "قتل قاچ قسمدر؟ قتلِ عمد نه در و حكمی نه در؟",
    "answer_tr": "قتل بش قسمدر:<br>١- قتلِ عمد ٢- قتلِ شبه عمد ٣- خطاءً قتل ٤- خطا مَجْرَاسنَه إجْرَا اُولُونَان قتل ٥- سبب ایله قتل<br>قتلِ عمد (قصدًا أولدورمك): سلاح و سلاح وظیفه‌سی كورن پارچالاییجی بر شیله أولدورمك دیمكدر. آغاچدن یاپیلان كسیجی آلتلر، طاش و آتش كبی. حكمی: گناهكارلق و قصاصدر. قصدًا أولدورمكده كفارت یوقدر.",
    "question_id": "Ada berapa macam pembunuhan? Apa itu pembunuhan sengaja (qatl 'amd) dan apa hukumnya?",
    "answer_id": "Pembunuhan ada lima macam:<br>1. Qatl 'amd (sengaja) 2. Qatl syibh 'amd (mirip sengaja) 3. Qatl khatha' (keliru) 4. Pembunuhan yang diberlakukan seperti khatha' 5. Pembunuhan karena sebab (tasabbub)<br>Qatl 'amd (membunuh dengan sengaja): membunuh dengan senjata atau benda tajam yang berfungsi sebagai senjata, seperti alat pemotong dari kayu, batu, dan api. Hukumnya: berdosa dan qisas. Dalam pembunuhan sengaja tidak ada kafarat.",
