    "originalNumber": 233,
    "question_tr": "شبه عمد قتل نه در و حكمی نه در؟",
    "answer_tr": "شبه عمد (قصدًا أولدورمیه بكزه‌ین أولدورمه): امام اعظم حضرتلرینه كوره سلاح و سلاحك یرینه قائم اولمایان بر شیله ووروب أولدورمكدر.<br>حكمی:گناهكار اولمق، كفارت و عَاقلَه اوزرینه دیتك لازم كلمه‌سیدر. بونده قصاص یوقدر. شبه عمدده قاتلك یاقینلرینه آغیر دیت دوشر.",
    "question_id": "Apa itu pembunuhan syibh 'amd (mirip sengaja) dan apa hukumnya?",
    "answer_id": "Syibh 'amd (pembunuhan yang menyerupai sengaja): menurut Imam A'zham, yaitu memukul hingga mati dengan sesuatu yang bukan senjata dan tidak menempati posisi senjata.<br>Hukumnya: berdosa, wajib kafarat, dan wajib diyat atas 'aqilah. Dalam hal ini tidak ada qisas. Dalam syibh 'amd, kerabat pembunuh menanggung diyat mughallazhah (berat).",
