    "question_tr": "خطاءً قتل و حكملری نه‌لردر؟",
    "answer_tr": "خطاءً قتل: یاكلیشلقله أولدورمك ایكی شكلده اولور:<br>قصدده خَطَا: بر انسانی آو ظن إیده‌رك، آتیپ أولدوردكدن صوكرا انسان اولدیغنی كورمك كبی.<br>فعلده خطا: اوقو هدفنه آتدیغی حالده بر انسانه إصابت إیتمه‌سی كبی.<br>حكمی: كفارت و عاقله اوزرینه دیتك لازم اولماسیدر. بوراده گناه یوقدر. چونكه غیرِ اختیاریدر.",
    "question_id": "Apa itu pembunuhan khatha' (keliru) dan apa hukum-hukumnya?",
    "answer_id": "Qatl khatha': membunuh karena keliru, terjadi dalam dua bentuk:<br>Keliru dalam maksud: seperti seseorang menembak manusia karena mengira hewan buruan, lalu setelah membunuhnya ternyata ia manusia.<br>Keliru dalam perbuatan: seperti seseorang memanah ke sasarannya tetapi mengenai manusia.<br>Hukumnya: wajib kafarat dan diyat atas 'aqilah. Di sini tidak ada dosa, karena terjadi di luar kehendak.",
