    "answer_tr": "قَسَامَه: قاتلی مجهول اولان و اوزرنده قَتْلْ اثری بولونان بر مقتولك بولوندیغی مَحَلْ آهالیسندن ٥٠ كیشیه، اونی أولدورمه‌دكلرینه و أولدوركنی بیلمه‌دكلرینه دائر یمین ایتدیریلمه‌سیدر. یمین ایتدكدن صوكره او محلله ساكینلرینه دیتی یوكله‌نیر. مَحَلَّه خَلْقی ٥٠ كیشیه تاملانامازسه، ٥٠ كیشی تمام اولونجیه قدر یمین تكرارلانیر.",
