    "answer_tr": "معاقل (عاقله لر): شبه عمد و خطأً قَتْلده واجب اولان دیت، أولدورولنك عاقله‌سنه فرض اولور. اكر قاتل دِیوَانَه یازیلمشلردن (مأمور) ایسه عاقله‌سی، دیوَانَه یازیلمشلرك هپسیدر. دیت اوچ سنه ظرفنده اونلرك مَعَاشْلرندن كسیلیر. دِیوَانْ اهلندن (مأمور) اولمایان بر كیمسه‌نك عاقله‌سی، قبیله‌سیدر. قصداً یاپیلان قَتْلك دیتی عاقله‌یه أُودَتْدیرِیلْمز.",
    "question_id": "Apa itu ma'aqil?",
    "answer_id": "Ma'aqil (para 'aqilah): diyat yang wajib dalam pembunuhan syibh 'amd (semi sengaja) dan khata' (keliru) menjadi kewajiban 'aqilah (keluarga penanggung) si pembunuh. Jika pembunuh termasuk orang yang terdaftar dalam diwan (pegawai negara), maka 'aqilah-nya adalah seluruh orang yang terdaftar dalam diwan tersebut. Diyat dipotong dari gaji mereka dalam jangka tiga tahun. Orang yang bukan ahli diwan (bukan pegawai), 'aqilah-nya adalah kabilahnya. Diyat pembunuhan yang dilakukan dengan sengaja tidak dibebankan kepada 'aqilah.",
