    "question_id": "Apa had zina? Apakah orang yang berzina disalatkan jenazahnya?",
    "answer_id": "Had zina: jika pelaku zina adalah muhshan dan muhshanah, maka dibunuh dengan dirajam (dilempari batu). Jika belum menikah (bikr), dicambuk seratus kali.<br>Muhshan dan muhshanah: laki-laki dan perempuan muslim, merdeka, berakal, dan balig yang pernah menjalani akad nikah yang sah. Orang yang berzina (lalu meninggal) dimandikan dan disalatkan jenazahnya.",
