    "answer_tr": "صید: آوْ دیمكدر. ذبایح: كسیلمه‌سی جائز اولان حیوانلر دیمكدر.<br>بوغازلامه‌ده كسیلن طَامَارْلَرْ:<br>١- نفس بوروسی<br>٢- یِیمَكْ و ایچمك بوروسی<br>٣- بوغازك ایكی طرفنده كی قان بورولری<br>بتون بو طامارلر كسیلدیكنده ییمه‌سی حلال اولور.<br>إمام اعظم حضرتلرینه كوره چوغونی كسرسه یینیر. إمامینه گوره؛ بونلردن بریسنك كسیلمه‌سی لازمدر دیدیلر.",
    "question_id": "Apa arti shaid dan dzabaih?",
    "answer_id": "Shaid: artinya hewan buruan. Dzabaih: artinya hewan-hewan yang boleh disembelih.<br>Urat-urat yang dipotong dalam penyembelihan:<br>1. Saluran napas (hulqum)<br>2. Saluran makan dan minum (mari')<br>3. Dua pembuluh darah di kedua sisi leher (wadajain)<br>Apabila semua urat ini terpotong, hewan itu halal dimakan.<br>Menurut Imam A'zham (Abu Hanifah), jika sebagian besarnya terpotong, hewan itu boleh dimakan. Menurut Imamain (Abu Yusuf dan Muhammad), mereka berkata: harus terpotong (sebagian besar) dari masing-masing urat tersebut.",
