    "question_tr": "كَلْبِ مُعَلَّمْ و دوغانك تعلیمی نه در؟",
    "answer_tr": "كلبِ مُعَلَّمْ، پارس و دوغان و آلیشدیریلمش هر یرتیجی حیوان ایله آولامق جائزدر.<br>كَلْبِكْ تعلیملی اولماسی: اوچ دفعه اوست اوسته آولادیغی حیواندن ییمه‌مسی در.<br>دوغانك تعلیملی اولماسی: چاغیردیغك زمان كَرِی كلمه‌سیله در.<br>آوجی، تَعْلِیمْلِی كَلْبِینی ویا دُوغَانِینی یاخود شَاهِینِینی آوَه كوندردیكی زمان، اللهك اسمنی ذكر ایدرسه او حیوانك طوتوب یاقالادیغی آو أُولُورْسَه ییلمه‌سی حلال اولور. كلب، آودن ییدیكی تقدیرده آوك أَتِی یینمز.<br>آتشه تاپان، مرتد و پوت پرستك آولادیغی حیوانلر یینمز. مسلمان و اهل كتابك بوغازلادیغی حلالدر.",
    "question_id": "Apa itu kalb mu'allam (anjing terlatih) dan bagaimana pelatihan elang?",
    "answer_id": "Berburu dengan kalb mu'allam (anjing terlatih), macan tutul, elang, dan setiap hewan buas yang telah dilatih hukumnya boleh.<br>Anjing dianggap terlatih apabila tiga kali berturut-turut tidak memakan hewan yang diburunya.<br>Elang dianggap terlatih apabila ia kembali ketika dipanggil.<br>Apabila pemburu melepas anjing, elang, atau rajawali yang terlatih untuk berburu dengan menyebut nama Allah, lalu buruan yang ditangkap hewan itu mati, maka halal dimakan. Jika anjing itu memakan sebagian buruan, daging buruan itu tidak boleh dimakan.<br>Hewan yang diburu oleh penyembah api, orang murtad, dan penyembah berhala tidak boleh dimakan. Sembelihan orang muslim dan ahli kitab halal.",
