    "question_tr": "یمین نه در، قاچ قسمدر و حكملری نه لردر؟",
    "answer_tr": "یمین: یمین إیده‌نك یاپمه‌یه ویا یاپمه‌میه كندیسیله عَزِمْ إیتدیكی قوتلی بر عقددن عبارتدر.<br>اوچ قسمدر:<br>١- یمین غموس: كچمش بر إیش ایچون، بیله بیله یالانله یمین ایتمكدر كه، بو یمینی ایدن كناهكار اولور. كفارت كركمز.<br>٢- یمین منعقده: كله‌جك بر امری یاپیپ ویا یاپمایاجغنه دائر یاپدیغی یمیندر. كیشی بو یمینی یرینه كتیرمزسه كفارت ویرمه‌سی لازم كلیر.<br>٣- یمین لغو: كچمش زمانده اولان بر شیئه، طوغری اولدیغنی ظن ایده‌رك ایتدیكی یمیندر. حالبوكه حقیقت بونك خلافه‌در. حضرت اللهك بو یمین سببیله صاحبنی مؤاخذه إیتمیه‌جكنی أمید ایده‌ریز.",
    "question_id": "Apa itu yamin (sumpah), ada berapa macam, dan apa hukum-hukumnya?",
    "answer_id": "Yamin: suatu ikatan kuat yang dengannya orang yang bersumpah bertekad untuk melakukan atau tidak melakukan sesuatu.<br>Ada tiga macam:<br>1. Yamin ghamus: bersumpah dusta dengan sengaja tentang suatu perkara yang telah lalu; orang yang bersumpah demikian berdosa. Tidak wajib kafarat.<br>2. Yamin mun'aqidah: sumpah untuk melakukan atau tidak melakukan suatu perkara di masa mendatang. Jika orang itu tidak memenuhi sumpahnya, wajib membayar kafarat.<br>3. Yamin laghwu: sumpah tentang sesuatu yang telah lalu dengan menyangka bahwa hal itu benar, padahal kenyataannya sebaliknya. Kami berharap Allah tidak menghukum pelakunya karena sumpah ini.",
