    "question_tr": "یمین هانكی لفظلر ایله اولور، یمین كفارتی نه در؟",
    "answer_tr": "یمین: لفظهء جلال (الله)، رحمٰن و رحیم كبی أللهك هر هانكی بر اسمی یاخود عِزَّةُ الله، جَلَالُ الله كبی بر ذاتی صفتیله یاپیلیر. یمین، قَسَمْ حرفلریله اولور، قَسَمْ حرفلری ایسه (وَاوْ، بَا و تَا) حرفلریدر. مثالی: وَالله، بِالله و تَالله در.<br>یمین كفارتی: بر كوله آزاد ایتمك ویا اون مسكینی كییدیرمك یاخوت طویورمق، بونلره كوجی یتمزسه پش پشه اوچ كون اوروچ طوتمقدر.",
    "question_id": "Dengan lafaz apa sumpah terjadi, dan apa kafarat sumpah?",
    "answer_id": "Yamin: dilakukan dengan lafzhul jalalah (Allah), atau dengan salah satu nama Allah seperti ar-Rahman dan ar-Rahim, atau dengan salah satu sifat dzat-Nya seperti 'izzatullah dan jalalullah. Sumpah terjadi dengan huruf-huruf qasam, yaitu huruf wawu, ba, dan ta. Contohnya: wallahi, billahi, dan tallahi.<br>Kafarat sumpah: memerdekakan seorang budak, atau memberi pakaian atau makan sepuluh orang miskin; jika tidak mampu melakukan semua itu, berpuasa tiga hari berturut-turut.",
