    "question_id": "Apa itu dakwa (gugatan)? Apa saja istilah-istilahnya?",
    "answer_id": "Da'wa: seseorang menuntut suatu hak dari orang lain di hadapan kadi (hakim).<br>Mudda'i (penggugat): orang yang menuntut haknya dalam suatu gugatan.<br>Mudda'a 'alaih (tergugat): orang yang dituntut haknya.<br>Mudda'a (bih): sesuatu yang menjadi objek gugatan.",
