    "question_tr": "شهادت و حكمی نه در؟",
    "answer_tr": "شهادت: كسین اولارق، ظن و تخمین اولمقسزك بر كیمسه نك، بر باشقه سنده اولان حقّنی خبر ویرمكدر.<br>بویله بر شهادتده بولونان كیشییه \"شاهد\"، لَهِنه شهادت یاپیلانه \"مشهودٌ له\"،علیهنه شهادت یاپیلانه \"مشهودٌ علیه\"، شهادت قونوسی اولان مسئله‌یه \"مشهودٌ به\" دینور.<br>حكمی: مدعِی طلب ایدرسه، شاهدلك ایتمك فرض اولور و ترك ایتمه سی حرام اولور. حدِّ شرعیی ایجاب ایتدیرن مسئله‌لرده ایكی شاهد مخیردر؛ دیلرلرسه أورترلر، دیلرلرسه اظهار ایدرلر. فقط كیزله ماك دها اویغوندر.",
    "question_id": "Apa itu syahadah (kesaksian) dan apa hukumnya?",
    "answer_id": "Syahadah: memberitakan secara pasti, tanpa dugaan dan perkiraan, tentang hak seseorang yang ada pada orang lain.<br>Orang yang memberikan kesaksian disebut \"syahid\", orang yang diuntungkan oleh kesaksian disebut \"masyhud lahu\", orang yang dirugikan oleh kesaksian disebut \"masyhud 'alaih\", dan perkara yang menjadi pokok kesaksian disebut \"masyhud bih\".<br>Hukumnya: jika mudda'i memintanya, bersaksi menjadi fardu dan meninggalkannya haram. Dalam perkara-perkara yang mewajibkan had syar'i, kedua saksi boleh memilih: jika mau mereka menutupinya, jika mau mereka menampakkannya. Namun menyembunyikannya lebih utama.",
