    "question_tr": "شهادت قاچ مرتبه اوزرینه در، شاهدلكك حكمی نه در؟",
    "answer_tr": "شهادتلر دورت مرتبه اوزرینه در:<br>١- زنا حقنده شاهدلكدر: بو شاهدلكده آنجاق دورت أركك معتبردر. قادینلرك شاهدلكی بوراده مقبول دكلدر.<br>٢- حد و قصاصده كبي مسئله‌لرده كی شاهدلك؛ بو كبی شاهدلكده ایكی كیشینك شاهدلكی قبول اولونور. قادینلرك شاهدلكی قبول اولونماز.<br>٣- بونلردن باشقه حقلرده؛ إیستر بو حق مال اولسون، إیستر نكاح، طلاق، وكالت و وصیت كبی مالی اولمیان دعوالر اولسون. ایكی أركك ویا بر أركك ایكی قادینك شاهدلكی قبول اولونور.<br>٤- طوغوم، باكره لك و اركككلرك مطلع اولماسی ممكن اولمایان یرلرده بولونان دیكر عیبلر حقنده تك بر خانمك شاهدلكی قبول اولونور.",
    "question_id": "Kesaksian ada berapa tingkatan, dan apa hukum kesaksian?",
    "answer_id": "Kesaksian ada empat tingkatan:<br>1. Kesaksian tentang zina: dalam kesaksian ini hanya empat orang laki-laki yang diterima. Kesaksian perempuan di sini tidak diterima.<br>2. Kesaksian dalam perkara seperti had dan qisas: dalam kesaksian seperti ini diterima kesaksian dua orang (laki-laki). Kesaksian perempuan tidak diterima.<br>3. Dalam hak-hak selain itu, baik berupa harta maupun gugatan yang bukan harta seperti nikah, talak, wakalah, dan wasiat: diterima kesaksian dua orang laki-laki, atau satu laki-laki dan dua perempuan.<br>4. Tentang kelahiran, keperawanan, dan cacat-cacat lain yang terdapat pada tempat yang tidak mungkin diketahui oleh laki-laki: diterima kesaksian seorang perempuan saja.",
