    "question_tr": "كیملرك شاهدلكی قبول ایدیلمز؟",
    "answer_tr": "١- ایكی كوزی كور اولانك، كوله‌نك، توبه ایتسه بیله افترادن دولایی حَدْ وورولانك شاهدلكی قبول اولونماز.<br>٢- بابانك اولادینه و طورونلرینه شاهدلكی، اولادك أبوینلرینه و اَجْدَادینه شاهدلكی قبول اولونماز.<br>٣- اَشْلَرك بربرلرینه، مولانك كوله سنه و مكاتبنه، اورتَاقْلردن بریسنك دیكرینك لَهِنْده یاپدیغی شاهدلك قبول اولونماز.<br>آغیتْجی قادینك، شَارْقیجی قَادینكْ، قوشلر ایله اوینایان كیمسه‌نك، انسانلره شَارْقی سویله‌یه‌نك، فائز ییه‌نك، طَاوْلَا و صَاتْرَانْج ایله قُومَارْ اوینایانك ایده‌نك شاهدلكی قبول اولونماز.",
    "question_id": "Siapa saja yang kesaksiannya tidak diterima?",
    "answer_id": "1. Kesaksian orang yang buta kedua matanya, budak, dan orang yang pernah dijatuhi had karena qadzaf (menuduh zina) meskipun ia telah bertobat, tidak diterima.<br>2. Kesaksian ayah untuk anak dan cucunya, serta kesaksian anak untuk kedua orang tua dan kakek-neneknya, tidak diterima.<br>3. Kesaksian suami-istri untuk satu sama lain, kesaksian tuan untuk budaknya dan budak mukatab-nya, serta kesaksian salah satu sekutu (mitra) untuk kepentingan sekutunya, tidak diterima.<br>Kesaksian perempuan peratap (meratapi mayit), perempuan penyanyi, orang yang bermain-main dengan burung, orang yang menyanyi untuk orang-orang, pemakan riba, dan orang yang berjudi dengan dadu (tawla) dan catur, tidak diterima.",
