    "question_tr": "اكراه نه در و قاچ قسمدر؟",
    "answer_tr": "اِكْرَاهْ: بر كیمسه‌یی تهدیدله، قورقوتمقله، رضاسی اولمقسزك بر سوزی سویله‌میه ویا بر إیشی إیشله‌میه زورلامقدر. إكراه ایكی قسمدر:<br>١- اكراهِ ملجی: أولدورمه ویا بر عضوی كسمك ایله یاپیلان إكراه در.<br>٢- اكراهِ غیر ملجی: دُوگْمَكْ ویا حبس ایتمكله یاپیلان إكراه در.",
    "question_id": "Apa itu ikrah (paksaan) dan ada berapa macam?",
    "answer_id": "Ikrah: memaksa seseorang dengan ancaman dan menakut-nakuti, tanpa kerelaannya, untuk mengucapkan suatu perkataan atau melakukan suatu perbuatan. Ikrah ada dua macam:<br>1. Ikrah mulji': paksaan dengan ancaman pembunuhan atau pemotongan anggota tubuh.<br>2. Ikrah ghairu mulji': paksaan dengan ancaman pemukulan atau penahanan (penjara).",
