    "chapterNameTr": "عقوبات",
    "chapterNameId": "Ukubat",
    "originalNumber": 262,
    "question_tr": "سِیَرْ نه در؟ غنیمت نصل تقسیم ایدیلیر؟",
    "answer_tr": "سِیَرْ: نبی علیه السلامك، غَزْوَه‌لرنده تعقیب ایتدیكی یوله مخصوصدر.<br>جِهَادْ: مسلمان، حر، بلوغ چاغینه أرمش اركككره فرضِ كفایه در. كوچوكه، كوله‌یه، قادینه، أعمی و كوتورومه فرض دكلدر.<br>غنیمت امام طرفندن تقسیم ایدیلیر. بشده برینی اللهك حقی اولارق آییریر. كری قالان دورت پایی غنیمتچیلر آراسنده تقسیم ایدر.<br>غنیمتك بشده بری ایسه اوچه تقسیم ایدیلیر. ١-یتیملره ٢-میسكینلره ٣-یولده قالانلره.",
    "question_id": "Apa itu siyar? Bagaimana ghanimah dibagikan?",
    "answer_id": "Siyar: khusus mengenai jalan (tata cara) yang ditempuh Nabi 'alaihissalam dalam peperangan-peperangan beliau.<br>Jihad: fardu kifayah atas laki-laki muslim, merdeka, yang telah mencapai usia balig. Tidak wajib atas anak kecil, budak, perempuan, orang buta, dan orang lumpuh.<br>Ghanimah dibagikan oleh imam. Ia memisahkan seperlimanya sebagai hak Allah, dan membagikan empat bagian sisanya di antara para pejuang yang memperoleh ghanimah.<br>Seperlima ghanimah itu dibagi menjadi tiga: 1. untuk anak-anak yatim, 2. untuk orang-orang miskin, 3. untuk ibnu sabil (orang yang terlantar dalam perjalanan).",
