    "question_tr": "مرتد كیمدر؟ مرتدده نصل بر معامله یاپیلیر؟",
    "answer_tr": "مُرْتَدْ: مسلمان ایكن دیندن چیقان، كافر اولان كیمسه در.<br>بر مسلمان اسلامدن دوندیكی زمان كندیسنه اسلامك حقیقتی آكلاتیلیر، شبهه‌سی وارسه ازاله ایدیلیر و اوچ كون حبسه آتیلیر. مسلمان اولورسه بیراقیلیر كفرنده اصرار ایدرسه أولدورولور. قادین مرتد اولورسه أولدورولمز، مسلمان اولونجیه قدر حبس اولونور.",
    "question_id": "Siapa murtad itu? Bagaimana perlakuan terhadap orang murtad?",
    "answer_id": "Murtad: orang yang keluar dari agama (Islam) setelah sebelumnya muslim, sehingga menjadi kafir.<br>Apabila seorang muslim keluar dari Islam, dijelaskan kepadanya hakikat Islam, syubhatnya dihilangkan jika ada, dan ia dipenjara selama tiga hari. Jika ia kembali masuk Islam, ia dibebaskan; jika ia bersikeras dalam kekufurannya, ia dibunuh. Jika perempuan murtad, ia tidak dibunuh, tetapi dipenjara sampai ia kembali masuk Islam.",
