    "answer_tr": "اسلام حقوقنه كوره آراضیلر عشر و خرج آراضیسی اولمق اوزره ایكییه آیریلیر:<br>١-عشر آراضیسی: مسلمان كیمسه لرك آراضیسندن \" اونده بر\" ویركیسنك آلیندیغی آراضیدر.<br>٢-خرج آراضیسی: آصلنده اهلِ كفره عائد ایكن اسلام اوردوسی طرفندن فتح ایدیلن طوپراقلر اولوب خرج ویركیسنه تابع اولان یرلردر.<br>جِزْیَه: اسلام مملكتلرنده، غیرِ مسلملردن حمایه و عسكرلكدن مُعَافِیَتْ قارشیلغنده آلینان شخص ویركیسیدر.",
