    "question_tr": "بغات كیملردر، بونلره نصل بر معامله یاپیلیر؟",
    "answer_tr": "بُغَاتْ: حقسز اولارق، حق امامه اطاعتدن چیقان كیمسه‌لردر.<br>مسلمانلردن بر غروب، بر بلده‌یی ألده ایدوب دولته قارشی باش قالدیریرسه، امام اوّلا اونلری جماعته دعوت ایدوب، شبهه‌لرینی ازاله‌یه چالیشمالیدر. اونلر باشلامادقجه حرب آچماز. حربه باشلادقلری تقدیرده، طوپلیلقلرینی داغیتنجیه قدر حرب ایدر. آرقالری اولورسه یارالیلرینی أولدورور، قاچانلرینی ده تعقیب ایتدیریر. آرقالری اولمازسه یارالیلری أولدورولمز، قاچانلری تعقیب ایدیلمز.توبه ایدینجیه قدر،امام ماللرینی حبس ایدوب اونلره كری ویرمز. فقط تقسیم ایده‌مز. توبه ایتدكلرنده ماللرینی كری اعاده ایدر.",
    "question_id": "Siapa bughat itu, dan bagaimana perlakuan terhadap mereka?",
    "answer_id": "Bughat: orang-orang yang tanpa hak keluar dari ketaatan kepada imam yang sah.<br>Apabila sekelompok kaum muslimin menguasai suatu negeri dan memberontak terhadap negara, imam pertama-tama mengajak mereka kembali kepada jamaah dan berusaha menghilangkan syubhat mereka. Selama mereka belum memulai, imam tidak memulai perang. Jika mereka memulai perang, imam memerangi mereka sampai kekuatan mereka tercerai-berai. Jika mereka memiliki pendukung (kelompok induk), yang terluka di antara mereka dibunuh dan yang melarikan diri dikejar. Jika mereka tidak memiliki pendukung, yang terluka tidak dibunuh dan yang melarikan diri tidak dikejar. Imam menahan harta mereka dan tidak mengembalikannya sampai mereka bertobat, tetapi tidak boleh membagikannya (sebagai ghanimah). Apabila mereka bertobat, harta mereka dikembalikan.",
