    "question_tr": "حَظْرْ و اِبَاحَه ایله علاقه‌لی مثاللری سویله‌یكز؟",
    "answer_tr": "ایپك كییمك اركككره حرام، قادینلره حلالدر.<br>اركك چوجوغه آلتون و ایپكلی كییدیرمك ولیسی ایچون مكروهدر.<br>آلتون و كموش قاپلردن ییمك ایچمك جائز دكلدر.<br>جَامْ بِیلُّورْ و عَقِیقْدن یاپیلان طاباقلرك قوللانیلماسنده هیچ بر بأس یوقدر.<br>كیشی، آنجاق اَجْنَبِیسی اولان بر خانمك یوزینه و بِیلَكْلَرِینَه قدر ایكی ألینه باقابیلیر.<br>خانمك خسته یرلرینه طَبِیبكْ باقماسی جائزدر.<br>دیز قاپاغی ایله كوبك آراسی خارج، اركك اركككك بدنینك دیكر قسمنه باقابیلیر، اركك، اركككك نه‌ره‌سنه باقابیلیرسه، خانمده اركككك عینی یرلرینه باقابیلیر.<br>اركك اركككك نه‌ره‌سنه باقابیلیرسه، خانمده خانمك اورالرینه باقابیلیر.<br>آلتون صویی ایله قرآنِ كریمی سوسله‌مك، جامعنك نَقِیشْ و زِینَتنِی یاپمقده بأس یوقدر.",
    "question_id": "Sebutkan contoh-contoh yang berkaitan dengan hazhr dan ibahah!",
    "answer_id": "Memakai sutra haram bagi laki-laki dan halal bagi perempuan.<br>Memakaikan emas dan sutra kepada anak laki-laki makruh bagi walinya.<br>Makan dan minum dari wadah emas dan perak tidak boleh.<br>Menggunakan piring yang terbuat dari kaca, kristal, dan batu akik tidak mengapa sama sekali.<br>Seorang laki-laki hanya boleh melihat wajah perempuan ajnabiyah (bukan mahram) dan kedua tangannya sampai pergelangan.<br>Dokter boleh melihat bagian tubuh perempuan yang sakit.<br>Laki-laki boleh melihat bagian tubuh laki-laki lain selain antara lutut dan pusar. Bagian mana pun dari laki-laki yang boleh dilihat oleh laki-laki, perempuan pun boleh melihat bagian yang sama dari laki-laki.<br>Bagian mana pun dari laki-laki yang boleh dilihat oleh laki-laki, perempuan pun boleh melihat bagian itu dari perempuan lain.<br>Menghiasi Al-Qur'an dengan air emas serta membuat ukiran dan hiasan masjid tidak mengapa.",
